import {image,makeCanvas} from './core.js';
export function assessPixels(data,width,height,sourceWidth=width,sourceHeight=height){
 const gray=new Float32Array(width*height);let brightness=0,dark=0,white=0;for(let i=0;i<gray.length;i++){const k=i*4,v=.2126*data[k]+.7152*data[k+1]+.0722*data[k+2];gray[i]=v;brightness+=v;if(v<30)dark++;if(v>247)white++;}brightness/=gray.length;let edge=0,detail=0,count=0;for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++){const i=y*width+x;const lap=4*gray[i]-gray[i-1]-gray[i+1]-gray[i-width]-gray[i+width];detail+=lap*lap;edge+=Math.abs(gray[i]-gray[i-1])+Math.abs(gray[i]-gray[i-width]);count++;}const sharpness=count?detail/count:0,contrast=count?edge/count:0;const warnings=[];if(Math.max(sourceWidth,sourceHeight)<1100)warnings.push('resolution');if(brightness<65)warnings.push('dark');if(contrast>1&&sharpness<45)warnings.push('blur');if(contrast<1)warnings.push('blank');return{brightness:Math.round(brightness),sharpness:Math.round(sharpness),warnings,darkFraction:dark/gray.length,whiteFraction:white/gray.length};
}
export async function assessImage(blob){const bitmap=await image(blob);try{const scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height)),canvas=makeCanvas(Math.max(3,Math.round(bitmap.width*scale)),Math.max(3,Math.round(bitmap.height*scale))),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);return assessPixels(ctx.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height,bitmap.width,bitmap.height);}finally{bitmap.close();}}
export const qualityMessages={resolution:'دقة الصورة منخفضة؛ اقترب من الورقة أو أعد التصوير.',dark:'الصورة داكنة؛ حسّن الإضاءة قبل التصوير.',blur:'قد تكون الصورة غير واضحة؛ ثبّت الهاتف وأعد التصوير.',blank:'التفاصيل قليلة؛ تأكد من ظهور النص والورقة.'};
